import asyncio
import json
from mcp.client.streamable_http import streamablehttp_client
from mcp import ClientSession

async def call_tool(tool_name, arguments=None):
    if arguments is None:
        arguments = {}
    async with streamablehttp_client("http://are-sidecar:8000/mcp") as (read, write, _):
        async with ClientSession(read, write) as session:
            await session.initialize()
            result = await session.call_tool(tool_name, arguments)
            for content in result.content:
                if hasattr(content, 'text'):
                    return content.text
            return str(result)

def run_tool(tool_name, arguments=None):
    return asyncio.run(call_tool(tool_name, arguments))

if __name__ == "__main__":
    import sys
    tool = sys.argv[1]
    args = json.loads(sys.argv[2]) if len(sys.argv) > 2 else {}
    print(run_tool(tool, args))
